def add_import(path, statement):
    full = os.path.join(ROOT, path)
    lines = open(full, encoding="utf-8").read().split("\n")
    if any(l.strip() == statement for l in lines):
        print("already applied: import in " + path)
        return
    idx = [i for i, l in enumerate(lines) if l.startswith("import ")]
    if not idx:
        fail("no imports found in " + path)
    target = idx[-1] + 1
    for i in idx:
        if lines[i] > statement:
            target = i
            break
    lines.insert(target, statement)
    open(full, "w", encoding="utf-8").write("\n".join(lines))
    print("added import to " + path)

