# ================================================================ 추가 수정분
# 아래는 처음 적용한 뒤 발견한 문제들을 고치는 패치입니다. 이미 예전 버전이 들어간
# 저장소에서도 동작하도록 전부 별도 sentinel 을 갖고 있습니다.

# ---------------------------------------------------------------- 예전 시도 정리
# 좌측 패널 색을 테마 속성으로 바꾸려던 파일들입니다. 되돌렸으므로 남아 있으면
# 지웁니다. 참조가 없는 리소스라 그냥 둬도 되지만, 깨끗하게 비웁니다.
for stale in (
    "AnkiDroid/src/main/res/color/drawer_item_text_soft.xml",
    "AnkiDroid/src/main/res/color/drawer_item_text_soft_night.xml",
    "AnkiDroid/src/main/res/drawable/drawer_item_background_soft.xml",
):
    stale_path = os.path.join(ROOT, stale)
    if os.path.exists(stale_path):
        os.remove(stale_path)
        print("removed stale file: " + stale)

def optional_patch(path, old, new, label, sentinel=None):
    """앵커가 없으면 실패시키지 않고 건너뜁니다. 원본이 바뀌어도 빌드는 계속됩니다."""
    full = os.path.join(ROOT, path)
    if not os.path.exists(full):
        print("skipped (file missing): " + label)
        return
    text = open(full, encoding="utf-8").read()
    marker = sentinel if sentinel is not None else new
    if marker in text or squash(marker) in squash(text):
        print("already applied: " + label)
        return
    if text.count(old) != 1:
        print("::warning::skipped " + label + " (anchor not found or ambiguous)")
        return
    open(full, "w", encoding="utf-8").write(text.replace(old, new))
    print("patched " + label)


