# ---------------------------------------------------------------- 파일 이름 추정
# 이름도 MIME 타입도 알려주지 않는 제공자에서 예외가 나고, 붙여넣기가 오류
# 보고서로 끝납니다. 내용을 읽어 이미지 종류를 알아내는 마지막 수단을 넣습니다.
optional_patch('AnkiDroid/src/main/java/com/ichi2/utils/ContentResolverUtil.kt',
               'import android.content.ContentResolver\nimport android.database.sqlite.SQLiteException',
               'import android.content.ContentResolver\nimport android.database.sqlite.SQLiteException\nimport android.graphics.BitmapFactory',
               "filename import for sniffing")

optional_patch('AnkiDroid/src/main/java/com/ichi2/utils/ContentResolverUtil.kt',
               '        // let this one throw\n        val filename = getFilenameViaMimeType(contentResolver, uri)\n        if (filename != null) {\n            return filename\n        }\n        throw IllegalStateException("Unable to obtain valid filename from uri: $uri")\n    }',
               '        // let this one throw\n        val filename = getFilenameViaMimeType(contentResolver, uri)\n        if (filename != null) {\n            return filename\n        }\n\n        // 파일 이름도 MIME 타입도 알려주지 않는 콘텐츠 제공자가 있습니다.\n        // 일부 앱이 클립보드에 넣는 URI 가 그렇습니다. 원본은 여기서 예외를 던지고,\n        // 그게 붙여넣기 실패와 오류 보고서로 이어집니다.\n        // 마지막 수단으로 내용을 조금 읽어 이미지 종류를 알아냅니다.\n        val sniffed = getExtensionBySniffing(contentResolver, uri)\n        if (sniffed != null) {\n            Timber.i("determined the type from the content: %s", sniffed)\n            return "image.$sniffed"\n        }\n        throw IllegalStateException("Unable to obtain valid filename from uri: $uri")\n    }\n\n    /**\n     * 내용의 머리 부분만 읽어 이미지 종류를 알아냅니다.\n     *\n     * inJustDecodeBounds 를 켜면 픽셀을 실제로 읽지 않고 형식만 확인합니다.\n     * 이름과 타입을 모두 알려주지 않는 제공자를 위한 마지막 수단입니다.\n     */\n    @CheckResult\n    private fun getExtensionBySniffing(\n        contentResolver: ContentResolver,\n        uri: Uri,\n    ): String? =\n        try {\n            val options = BitmapFactory.Options().apply { inJustDecodeBounds = true }\n            contentResolver.openInputStream(uri).use { stream ->\n                if (stream == null) return null\n                BitmapFactory.decodeStream(stream, null, options)\n            }\n            options.outMimeType?.let { MimeTypeMap.getSingleton().getExtensionFromMimeType(it) }\n        } catch (e: Exception) {\n            Timber.w(e, "could not detect the image type from its content")\n            null\n        }',
               "filename by sniffing content")

# ---------------------------------------------------------------- 진단 토스트 제거
optional_patch('AnkiDroid/src/main/java/com/ichi2/anki/FieldEditText.kt',
               '            if (pastePlainText()) return true\n\n            // 여기까지 왔다는 건 클립보드에서 아무것도 못 꺼냈다는 뜻입니다.\n            // 원인을 알 수 있도록 무엇이 들어 있었는지 보여줍니다.\n            clipboard?.primaryClip?.let { clip ->\n                val types =\n                    clip.description?.let { d ->\n                        (0 until d.mimeTypeCount).joinToString(", ") { d.getMimeType(it) }\n                    } ?: "none"\n                val message = "Clipboard: $types (items: ${clip.itemCount})"\n                Timber.w("nothing pasted. %s", message)\n                com.ichi2.anki.common.utils.android.showThemedToast(context, message, false)\n            }\n            return false',
               '            return pastePlainText()',
               "remove paste diagnostic toast")

# ---------------------------------------------------------------- 붙여넣기 정규화
# 이름을 못 얻는 URI 는 내용을 읽어 파일로 만든 뒤 넘깁니다.
# 이미지 가리기의 클립보드 불러오기가 쓰는 방식과 같습니다.
optional_patch('AnkiDroid/src/main/java/com/ichi2/anki/noteeditor/NoteEditorMultimediaController.kt',
               '        val context = fragment.requireContext()\n        val mediaTag =\n            MediaRegistration.onPaste(\n                context,\n                uri,\n                description,\n                pasteAsPng,\n                showError = { type -> fragment.showSnackbar(type.toHumanReadableString(context)) },\n            ) ?: return false',
               '        val context = fragment.requireContext()\n        // 콘텐츠 제공자가 파일 이름도 MIME 타입도 알려주지 않는 경우가 있습니다.\n        // 그러면 아래 파이프라인이 이름을 못 정해 예외를 던지고, 붙여넣기가 오류\n        // 보고서로 끝납니다. 이미지 가리기의 클립보드 불러오기는 제공자에게 아무것도\n        // 묻지 않고 내용만 읽어 파일로 만들기 때문에 잘 동작합니다. 같은 방식으로\n        // 먼저 파일을 만들어 두고, 그 파일을 넘깁니다.\n        val (mediaUri, mediaDescription) = copyIfUnnamed(uri, description)\n        val mediaTag =\n            MediaRegistration.onPaste(\n                context,\n                mediaUri,\n                mediaDescription,\n                pasteAsPng,\n                showError = { type -> fragment.showSnackbar(type.toHumanReadableString(context)) },\n            ) ?: return false',
               "normalise pasted media")

optional_patch('AnkiDroid/src/main/java/com/ichi2/anki/noteeditor/NoteEditorMultimediaController.kt',
               '    /** Imports the captured media into the collection if the result carries any. */\n    fun handleResult(result: MultimediaResult.Success) {',
               '    /**\n     * 이름을 알아낼 수 있는 URI 는 그대로 씁니다. 드래그 앤 드롭으로 들어온 이미지는\n     * 원래 파일 이름을 그대로 유지합니다.\n     *\n     * 이름을 못 얻는 URI 는 내용을 읽어 캐시에 파일로 만들고 그 파일을 대신 넘깁니다.\n     * 외부 캐시에 두는 이유는 아래 파이프라인이 /data 아래 경로를 거부하기 때문입니다.\n     */\n    private fun copyIfUnnamed(\n        uri: Uri,\n        description: ClipDescription,\n    ): Pair<Uri, ClipDescription> {\n        val context = fragment.requireContext()\n        val resolver = context.contentResolver\n\n        val named =\n            try {\n                ContentResolverUtil.getFileName(resolver, uri)\n                true\n            } catch (e: Exception) {\n                Timber.i(e, "the provider gave no filename, copying the content instead")\n                false\n            }\n        if (named) return uri to description\n\n        val directory = context.externalCacheDir ?: return uri to description\n\n        return try {\n            // 내용의 머리 부분만 읽어 실제 형식을 알아냅니다.\n            val options = android.graphics.BitmapFactory.Options().apply { inJustDecodeBounds = true }\n            resolver.openInputStream(uri).use { header ->\n                android.graphics.BitmapFactory.decodeStream(header, null, options)\n            }\n            val mimeType = options.outMimeType ?: "image/jpeg"\n            val extension =\n                android.webkit.MimeTypeMap\n                    .getSingleton()\n                    .getExtensionFromMimeType(mimeType) ?: "jpg"\n\n            val target = File.createTempFile("pasted", ".$extension", directory)\n            resolver.openInputStream(uri).use { input ->\n                if (input == null) {\n                    target.delete()\n                    return uri to description\n                }\n                target.outputStream().use { output -> input.copyTo(output) }\n            }\n            if (target.length() == 0L) {\n                target.delete()\n                return uri to description\n            }\n\n            Timber.i("copied the pasted media to %s", target.name)\n            Uri.fromFile(target) to ClipDescription(description.label, arrayOf(mimeType))\n        } catch (e: Exception) {\n            Timber.w(e, "could not copy the pasted media, using the original uri")\n            uri to description\n        }\n    }\n\n    /** Imports the captured media into the collection if the result carries any. */\n    fun handleResult(result: MultimediaResult.Success) {',
               "pasted media copy helper",
               sentinel="private fun copyIfUnnamed(")

# ---------------------------------------------------------------- CheckResult 대응
# getFileName 에는 @CheckResult 가 붙어 있어 반환값을 버리면 lint 가 막습니다.
# 결과를 받아서 판단하도록 바꿉니다.
optional_patch('AnkiDroid/src/main/java/com/ichi2/anki/noteeditor/NoteEditorMultimediaController.kt',
               '        val named =\n            try {\n                ContentResolverUtil.getFileName(resolver, uri)\n                true\n            } catch (e: Exception) {\n                Timber.i(e, "the provider gave no filename, copying the content instead")\n                false\n            }\n        if (named) return uri to description',
               '        val existingName =\n            try {\n                ContentResolverUtil.getFileName(resolver, uri)\n            } catch (e: Exception) {\n                Timber.i(e, "the provider gave no filename, copying the content instead")\n                null\n            }\n        if (existingName != null) return uri to description',
               "use the getFileName result")

# ---------------------------------------------------------------- 확장자 없는 이름
# 이름을 받아도 확장자가 없으면 파이프라인이 예외를 던집니다.
# 같은 기준으로 미리 걸러내고, 그런 경우에도 내용을 복사하도록 합니다.
optional_patch('AnkiDroid/src/main/java/com/ichi2/anki/noteeditor/NoteEditorMultimediaController.kt',
               '    private fun copyIfUnnamed(',
               "    /** 파일 이름에서 확장자를 가르는 문자. */\n    private val DOT = '.'\n\n    private fun copyIfUnnamed(",
               "dot constant for the extension check")

optional_patch('AnkiDroid/src/main/java/com/ichi2/anki/noteeditor/NoteEditorMultimediaController.kt',
               '        val existingName =\n            try {\n                ContentResolverUtil.getFileName(resolver, uri)\n            } catch (e: Exception) {\n                Timber.i(e, "the provider gave no filename, copying the content instead")\n                null\n            }\n        if (existingName != null) return uri to description',
               '        // 이름을 받아도 확장자가 없으면 소용이 없습니다. 아래 파이프라인은\n        // FileNameAndExtension.fromString 으로 이름을 쪼개는데, 점이 없으면 null 을\n        // 돌려주고 "Unable to determine valid filename" 예외가 납니다. 그 예외가\n        // 오류 보고서로 이어집니다. 여기서 같은 기준으로 미리 걸러냅니다.\n        val existingName =\n            try {\n                ContentResolverUtil\n                    .getFileName(resolver, uri)\n                    .takeIf { name -> name.lastIndexOf(DOT) >= 1 }\n            } catch (e: Exception) {\n                Timber.i(e, "the provider gave no filename, copying the content instead")\n                null\n            }\n        if (existingName != null) return uri to description\n        Timber.i("no usable filename for the pasted media, copying the content instead")',
               "require a usable extension")

# ---------------------------------------------------------------- 중복 삽입 정리
# 함수를 넣는 패치는 나중 패치가 그 함수 안을 고치면 표식이 사라져, 다음 실행 때
# 같은 함수를 또 넣습니다. 위에서 표식을 명시해 재발은 막았고, 여기서는 이미
# 들어간 중복본을 지웁니다. 뒤에 나오는 쪽을 지우므로, 그동안의 수정이 반영된
# 앞쪽 정의가 남습니다.
def remove_duplicate_member(path, header, label):
    full = os.path.join(ROOT, path)
    if not os.path.exists(full):
        return
    text = open(full, encoding="utf-8").read()
    removed = 0
    while text.count(header) > 1:
        start = text.rindex(header)
        doc = text.rfind("    /**", 0, start)
        if doc != -1:
            close = text.find("*/", doc)
            if close != -1 and close < start and text[close + 2:start].strip() == "":
                start = doc
        brace = text.index("{", text.rindex(header))
        depth = 0
        end = None
        for index in range(brace, len(text)):
            if text[index] == "{":
                depth += 1
            elif text[index] == "}":
                depth -= 1
                if depth == 0:
                    end = index + 1
                    break
        if end is None:
            break
        while end < len(text) and text[end] == "\n":
            end += 1
        text = text[:start] + text[end:]
        removed += 1
    if removed:
        open(full, "w", encoding="utf-8").write(text)
        print("removed %d duplicate definition(s): %s" % (removed, label))
    else:
        print("no duplicates: " + label)


remove_duplicate_member('AnkiDroid/src/main/java/com/ichi2/anki/noteeditor/NoteEditorMultimediaController.kt', "    private fun copyIfUnnamed(", "copyIfUnnamed")
remove_duplicate_member('AnkiDroid/src/main/java/com/ichi2/anki/FieldEditText.kt', "    private fun firstMediaUri(", "firstMediaUri")
remove_duplicate_member('AnkiDroid/src/main/java/com/ichi2/anki/FieldEditText.kt', "    private fun firstMediaItem(", "firstMediaItem")

# ---------------------------------------------------------------- DOT 상수 제거
# 상수를 넣는 패치가 건너뛰어져도 그 상수를 쓰는 코드는 들어갈 수 있습니다.
# 상수 없이 문자열로 비교하도록 바꿉니다. 원본의 FileNameAndExtension 도
# lastIndexOf(".") 로 같은 판단을 합니다.
optional_patch('AnkiDroid/src/main/java/com/ichi2/anki/noteeditor/NoteEditorMultimediaController.kt',
               '                    .takeIf { name -> name.lastIndexOf(DOT) >= 1 }',
               '                    .takeIf { name -> name.lastIndexOf(".") >= 1 }',
               "compare the extension without a constant")

def remove_text(path, block, label):
    full = os.path.join(ROOT, path)
    if not os.path.exists(full):
        return
    text = open(full, encoding="utf-8").read()
    if block not in text:
        print("nothing to remove: " + label)
        return
    open(full, "w", encoding="utf-8").write(text.replace(block, ""))
    print("removed " + label)

remove_text('AnkiDroid/src/main/java/com/ichi2/anki/noteeditor/NoteEditorMultimediaController.kt',
            "    /** 파일 이름에서 확장자를 가르는 문자. */\n    private val DOT = '.'\n\n",
            "the DOT constant")

print("all patches applied")
